package com.bank.report;

import java.util.*;
import java.util.logging.*;

public class ReportDemo {
    private static final Logger log = Logger.getLogger("Report");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> employees = List.of(
            new Employee("Rajesh", 1200000), new Employee("Priya", 900000),
            new Employee("Sneha", 1500000), new Employee("Amit", 700000));
        HighEarnerReport report = new HighEarnerReport(log);

        List<String> names = report.highEarnerNames(employees, 1_000_000);
        log.info(() -> "Report output (names only): " + names);
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final double salary;
    Employee(String name, double salary) { this.name = name; this.salary = salary; }
    String getName() { return name; }
    double getSalary() { return salary; }
}

// ─── Would be in service/HighEarnerReport.java ───
class HighEarnerReport {
    private final Logger log;
    HighEarnerReport(Logger log) { this.log = log; }

    List<String> highEarnerNames(List<Employee> employees, double threshold) {
        return employees.stream()
            .filter(e -> e.getSalary() > threshold)
            // peek: AUDIT only — logs who passed, returns element UNCHANGED
            .peek(e -> log.info(() -> "AUDIT passed filter: " + e.getName()))
            .map(Employee::getName)
            .collect(java.util.stream.Collectors.toList());
    }
}
